# Artist reference table: match key (lowercase pinyin, as museums spell it) ->
# (display name, Chinese, dates, school, short note).
# Notes are written from general art-history knowledge, not copied from any source.
A = {}
def a(keys, name, zh, dates, school, note):
    for k in keys.split('|'):
        A[k.strip().lower()] = dict(name=name, zh=zh, dates=dates, school=school, note=note)

